@font-face { font-family: Soehne; src: url("/fonts/soehne-halbfett.woff2") format("woff2"); font-weight: 600; font-display: swap; font-style: normal; }
.dark .dark-invert { filter: invert(1); }
.hover\:bg-\[var\(--bg-card-hover\)\]:hover { background-color: var(--bg-card-hover); }
.hover\:text-\[var\(--text-primary\)\]:hover { color: var(--text-primary); }
